sourceCode['time-range.ts'] = ''
  + 'type TimeRange = {\n'
  + '  from: TimeValue;\n'
  + '  to: TimeValue;\n'
  + '  tz: number;\n'
  + '};\n'
  + '\n'
  + 'type ParsedTimeRange = {\n'
  + '  from: ParsedTimeValue;\n'
  + '  to: ParsedTimeValue;\n'
  + '  tz: number;\n'
  + '};\n'
  + '\n'
  + 'type ParsedTimeRangeResult =\n'
  + '  | { ok: true; value: ParsedTimeRange }\n'
  + '  | { ok: false; error: string };\n'
  + '\n'
  + 'function safeParseTimeRange(range: TimeRange): ParsedTimeRangeResult {\n'
  + '  const fromResult = safeParseTimeValue(range.from);\n'
  + '  const toResult = safeParseTimeValue(range.to);\n'
  + '  if (!fromResult.ok || !toResult.ok) {\n'
  + '    return { ok: false, error: "Invalid time range" };\n'
  + '  }\n'
  + '  return {\n'
  + '    ok: true,\n'
  + '    value: { from: fromResult.value, to: toResult.value, tz: range.tz },\n'
  + '  };\n'
  + '}\n'
  + '\n'
  + 'type ResolvedTimeRange = {\n'
  + '  from: Date;\n'
  + '  to: Date;\n'
  + '};\n'
  + '\n'
  + 'type ResolvedTimeRangeResult =\n'
  + '  | { ok: true; value: ResolvedTimeRange }\n'
  + '  | { ok: false; error: string };\n'
  + '\n'
  + 'function safeResolveTimeRange(range: TimeRange): ResolvedTimeRangeResult {\n'
  + '  const fromResult = safeParseTimeValue(range.from);\n'
  + '  const toResult = safeParseTimeValue(range.to);\n'
  + '  if (!fromResult.ok || !toResult.ok) {\n'
  + '    return { ok: false, error: "Invalid time range" };\n'
  + '  }\n'
  + '\n'
  + '  const from = fromResult.value;\n'
  + '  const to = toResult.value;\n'
  + '\n'
  + '  try {\n'
  + '    return {\n'
  + '      ok: true,\n'
  + '      value: {\n'
  + '        from: resolveParsedTimeValue(from, range.tz),\n'
  + '        to: resolveParsedTimeValue(to, range.tz),\n'
  + '      },\n'
  + '    };\n'
  + '  } catch (error) {\n'
  + '    return {\n'
  + '      ok: false,\n'
  + '      error: error instanceof Error ? error.message : "Unknown error",\n'
  + '    };\n'
  + '  }\n'
  + '}\n'
  + '\n'
  + 'function resolveParsedTimeValue(value: ParsedTimeValue, tz: number): Date {\n'
  + '  const result = resolveParsedTimeValueExpr(value.expr, tz);\n'
  + '  if (result.t === "date") {\n'
  + '    return result.value;\n'
  + '  }\n'
  + '  throw new Error(`Unexpected result`);\n'
  + '}\n'
  + '\n'
  + 'function resolveDuration(amount: number, unit: "m" | "h" | "d" | "y"): number {\n'
  + '  switch (unit) {\n'
  + '    case "m":\n'
  + '      return amount * 60 * 1000;\n'
  + '    case "h":\n'
  + '      return amount * 60 * 60 * 1000;\n'
  + '    case "d":\n'
  + '      return amount * 24 * 60 * 60 * 1000;\n'
  + '    case "y":\n'
  + '      return amount * 365 * 24 * 60 * 60 * 1000;\n'
  + '  }\n'
  + '}\n'
  + '\n'
  + 'function resolveParsedTimeValueExpr(\n'
  + '  expr: ParsedTimeValueExpr,\n'
  + '  tz: number,\n'
  + '):\n'
  + '  | { t: "date"; value: Date }\n'
  + '  | { t: "duration"; amount: number; unit: "m" | "h" | "d" | "y" } {\n'
  + '  if (expr.t === "atom") {\n'
  + '    return resolveParsedTimeValueAtom(expr.atom, tz);\n'
  + '  }\n'
  + '  if (expr.t === "add") {\n'
  + '    const left = resolveParsedTimeValueExpr(expr.left, tz);\n'
  + '    const right = resolveParsedTimeValueExpr(expr.right, tz);\n'
  + '\n'
  + '    if (left.t !== "date") {\n'
  + '      throw new Error(`Left operand is not a date: ${left.t}`);\n'
  + '    }\n'
  + '    if (right.t !== "duration") {\n'
  + '      throw new Error(`Right operand is not a duration: ${right.t}`);\n'
  + '    }\n'
  + '\n'
  + '    return {\n'
  + '      t: "date",\n'
  + '      value: new Date(\n'
